/**
 * Runs the document-generation engine. Resolves the persona's clearance, applies the audience gate (external caps sources to public BEFORE retrieval), retrieves permission-filtered evidence, composes a cited draft, and runs the Brand Guardian. Returns an honest no_evidence / permission_blocked state when nothing can be safely produced.
 * @summary Generate a governed document (messaging, press+Q&A, or multi-format)
 */



export const GenerateBody = zod.object({
  "shape": zod.string().describe('messaging | press | multiformat | visualdeck'),
  "topic": zod.string().min(1),
  "roleId": zod.string().describe('Active persona id (drives clearance)'),
  "audience": zod.string().describe('internal | external'),
  "templateId": zod.string().nullish().describe('Optional brand template chosen in the Generate tab. When present and valid it drives the section blueprint, required disclaimers and default export template.\n'),
  "language": zod.string().optional().describe('BCP-47-ish code, e.g. en, es'),
  "confidentiality": zod.string().optional().describe('Destination confidentiality of the document'),
  "format": zod.string().optional().describe('Output format hint, e.g. document, email, note'),
  "axisIds": zod.array(zod.string()).optional(),
  "spokesperson": zod.string().nullish().describe('Named spokesperson for quotes and spokesperson notes'),
  "eventDate": zod.string().nullish().describe('Event or publication date framing the document'),
  "kpiContext": zod.union([zod.null(),zod.object({
  "period": zod.string().describe('week | month | quarter | custom'),
  "rangeFrom": zod.string().nullish().describe('Custom range start (YYYY-MM-DD) when period is custom'),
  "rangeTo": zod.string().nullish().describe('Custom range end (YYYY-MM-DD) when period is custom'),
  "area": zod.string(),
  "axisId": zod.string().nullish(),
  "market": zod.string().nullish(),
  "brand": zod.string().nullish(),
  "source": zod.string().nullish(),
  "initiativeType": zod.string().nullish(),
  "objectiveId": zod.string().nullish()
})]).optional().describe('Structured KPI panel context handed over from the KPIs page. Carries the active filters only — the engine recomputes every figure server-side under the persona\'s clearance (fail closed) before any of it reaches the composer.\n'),
  "askContext": zod.union([zod.null(),zod.object({
  "question": zod.string().describe('The original Ask question.'),
  "citedDocIds": zod.array(zod.string()).describe('Corpus document ids cited by the Ask answer.'),
  "status": zod.string().nullish().describe('answered | conflict (display hint only; never trusted for access)'),
  "historic": zod.boolean().nullish(),
  "lowConfidence": zod.boolean().nullish()
})]).optional().describe('Structured Ask answer handoff from the Ask page. Carries the original question, the cited document ids and honest status flags only — never snippets or answer text. The engine re-derives every cited source\'s accessibility server-side under the CURRENT persona\'s clearance and the destination gate (fail closed), so a tampered or stale payload can never surface content the persona could not retrieve itself.\n'),
  "attachments": zod.union([zod.null(),zod.object({
  "pastedText": zod.string().nullish().describe('Pasted brief or data provided by the user.'),
  "links": zod.array(zod.string()).optional().describe('Governed source links or references named by the user.')
})]).optional().describe('User-provided brief attachments (pasted brief\/data and governed source links). Passed to the composer as clearly labeled user-provided context only — never treated as governed evidence, never cited, and never folded into retrieval.\n'),
  "layoutIds": zod.array(zod.string()).nullish().describe('Optional visual-deck layout selection. When present and non-empty the slide composer builds the deck from these pool layouts only (the cover and closing layouts stay available so the deck frame is never broken). Ids must come from GET \/generate\/visual-layouts; unknown ids are rejected with 400. Ignored for non-visualdeck shapes.\n'),
  "deckLength": zod.string().nullish().describe('Visual-deck target length: standard (~12-16 slides, single-pass), extended (~25-35 slides) or full (~40-60 slides). Extended and full run a chaptered multi-pass composition with per-chapter governed retrieval; the deck honestly shrinks when the permitted corpus cannot support the requested length. Ignored for non-visualdeck shapes. Absent = standard.\n')
})

